import { Pricing } from "march/landing"
import { Button } from "march/ui"

// kedi maması aboneliği: kedi sayısı arttıkça fiyatlar sayaç gibi döner
export function CatFood() {
  let $cats = 1
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Button variant="secondary" on:click={() => $cats = Math.max(1, $cats - 1)}>– Kedi</Button>
      <span sx={{ text: "xl" }}>{"🐱".repeat($cats)}</span>
      <Button variant="secondary" on:click={() => $cats = Math.min(5, $cats + 1)}>+ Kedi</Button>
    </div>
    {() => {
      const cats = $cats
      return <Pricing currency="TRY" saving="1 ay bedava" plans={[
      { name: "Kuru mama", price: { monthly: 250 * cats, yearly: 230 * cats }, features: [`${cats * 3} kg / ay`, "Kapıya teslim"] },
      { name: "Gurme", price: { monthly: 420 * cats, yearly: 380 * cats }, featured: true, badge: "Miyav!", features: [`${cats * 3} kg / ay`, "Haftada 2 yaş mama", "Oyuncak sürprizi"] },
    ]} />
    }}
  </div>
}

import { Pricing } from "march/landing"
import { toast } from "march/ui"

// bir spor salonunun üyelik sayfası: aylık / yıllık seçimi dışarıda tutulur (bind:period), seçilen plana göre bildirim
export function GymPlans() {
  let $period: string = "monthly"
  const join = (name: string) => () => toast(`${name} üyeliği (${$period === "yearly" ? "yıllık" : "aylık"}) sepete eklendi`)
  return <div sx={{ flex: "col", gap: 3 }}>
    <Pricing bind:period={$period} currency="TRY" saving="2 ay bedava" featureColor="brand-green" plans={[
      { name: "Gündüz", description: "Hafta içi 07.00–16.00", price: { monthly: 900, yearly: 750 }, features: ["Fitness alanı", "Soyunma odası", { label: "Grup dersleri", included: false }], cta: { label: "Gündüz'e katıl", onClick: join("Gündüz") } },
      { name: "Tam", description: "Her gün, her saat", price: { monthly: 1400, yearly: 1150 }, featured: true, badge: "En çok seçilen", features: ["Fitness alanı", "Grup dersleri", "Havuz ve sauna", { label: "Kişisel antrenör", hint: "ayda 1 seans" }], cta: { label: "Tam üyelik al", onClick: join("Tam") } },
      { name: "Kurumsal", description: "10 kişi ve üstü ekipler", price: null, features: ["Ekip panosu", "Faturalı ödeme"], cta: { label: "Bize ulaşın", href: "#iletisim" } },
    ]} labels={{ custom: "Teklif alın" }} />
  </div>
}

import { Pricing } from "march/landing"
import { Card, Segmented, Toggle } from "march/ui"

// Pricing'in bütün özellikleri bir arada: planlar (name, description, price, features, cta, featured, badge), dönem
// (period + setPeriod = bind:period), düğme (toggle), para birimi (currency), kazanç etiketi (saving), özellik işareti
// (featureIcon) ve rengi (featureColor), ay satırı (per), fiyat geçişi (priceEffect), giriş (reveal), kendi metinler
// (labels) ve sınıf (class)
type BillingPeriod = "monthly" | "yearly"
const EFFECTS = ["none", "roll", "count"] as const

export function PricingLab() {
  let $period = "monthly" as BillingPeriod
  let $effect: (typeof EFFECTS)[number] = "none"
  let $toggle = true
  let $per = true
  let $ownMark = false
  let $chosen = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Fiyat geçişi" options={EFFECTS.map((e) => ({ value: e, label: e }))} bind:value={$effect} />
        <Toggle label="Dönem düğmesi" bind:value={$toggle} />
        <Toggle label="Ay satırı" bind:value={$per} />
        <Toggle label="Kendi işaretim" bind:value={$ownMark} />
      </div>
    </Card>
    {() => {
      // bu satırda okunan durumlar değişince fiyatlar yeniden çizilir; dönem bir işlev (period), kendisi güncellenir
      const toggle = $toggle, effect = $effect, per = $per, ownMark = $ownMark, chosen = $chosen
      return <Pricing class="lab-pricing" period={() => $period} setPeriod={(p: BillingPeriod) => $period = p} toggle={toggle}
      currency="EUR" saving="3 ay bedava" priceEffect={effect} per={per} featureColor="brand-purple"
      featureIcon={ownMark ? (on: boolean) => (on ? "✓" : "✗") : true}
      reveal={{ effect: "scale", stagger: 60 }}
      labels={{ monthly: "Aylık", yearly: "Yıllık", perMonth: "/ ay", billedMonthly: "aylık ödenir", billedYearly: "yıllık ödenir", custom: "Bize sorun", billingPeriod: "Ödeme dönemi", notIncluded: "dahil değil" }}
      plans={[
        { name: "Başlangıç", description: "Tek kişi için", price: 0, features: ["1 proje", { label: "Ekip", included: false }], cta: { label: "Ücretsiz başla" } },
        { name: "Pro", description: "Büyüyen ekipler", price: { monthly: 30, yearly: 24 }, featured: true, badge: "Önerilen", features: ["Sınırsız proje", { label: "Öncelikli destek", hint: "24 saat içinde" }], cta: { label: `Pro'yu seç (${chosen})`, onClick: () => $chosen++ } },
        { name: "Kurum", price: null, features: ["Özel sözleşme"], cta: { label: "Görüşelim", href: "#kurum" } },
      ]} />
    }}
    <p sx={{ color: "muted" }}>{`Dönem: ${$period}`}</p>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PricingLab } from "./PricingLab.tsx"

// PricingLab'in testleri: kaydedince Testler sekmesinde çalışır
test("üç plan; öne çıkan rozetli, özel fiyat kendi metniyle", () => {
  const s = renderTest(() => <PricingLab />)
  expect(s.all(".lab-pricing .m-price-card").length).toBe(3)
  expect(s.get(".m-price-card.is-featured .m-price-badge")?.textContent).toBe("Önerilen")
  expect(s.get(".m-price-custom")?.textContent).toBe("Bize sorun")
  expect(s.get(".m-price-feat.is-off")?.textContent).toContain("dahil değil")
})

test("Yıllık'a basınca dönem değişir, fiyat ve satır güncellenir", async () => {
  const s = renderTest(() => <PricingLab />)
  const before = s.all(".m-price-plain")[1]?.textContent
  await s.click("Yıllık")
  expect(s.sees("Dönem: yearly")).toBe(true)
  expect(s.all(".m-price-plain")[1]?.textContent).not.toBe(before)
  expect(s.get(".m-price-billed")?.textContent).toBe("yıllık ödenir")
})

test("eylem sayar; kendi işaret anahtarı işareti değiştirir", async () => {
  const s = renderTest(() => <PricingLab />)
  await s.click("Pro'yu seç (0)")
  expect(s.find("Pro'yu seç (1)")).not.toBe(null)
  expect(s.get(".m-price-feat-own")).toBe(null)
  await s.click("Kendi işaretim")
  expect(s.get(".m-price-feat-own")?.textContent).toBe("✓")
})

test("dönem düğmesi ve ay satırı kapanır", async () => {
  const s = renderTest(() => <PricingLab />)
  await s.click("Dönem düğmesi")
  await s.click("Ay satırı")
  expect(s.get(".m-price-switch")).toBe(null)
  expect(s.get(".m-price-per")).toBe(null)
})
